blocks.content:
erDiagram
    DEPARTMENT ||--o{ EMPLOYEE : "소속된다 (비식별자 관계)"
    EMPLOYEE ||--o{ ORDER : "담당한다 (비식별자 관계)"
    ORDER ||--|{ ORDER_ITEM : "포함한다 (식별자 관계)"
    PRODUCT ||--o{ ORDER_ITEM : "참조된다 (비식별자 관계)"

    DEPARTMENT {
        string dept_no PK "부서번호 (내부/단일/원조)"
        string dept_name "부서명"
    }
    EMPLOYEE {
        string emp_no PK "사원번호 (주식별자/내부/단일)"
        string ssn UK "주민번호 (보조식별자/원조)"
        string name "사원명"
        string dept_no FK "부서번호 (외부식별자)"
    }
    ORDER {
        string order_id PK "주문번호 (대리식별자/주식별자)"
        date order_date "주문일자"
        string emp_no FK "담당사원번호 (외부식별자)"
    }
    ORDER_ITEM {
        string order_id PK,FK "주문번호 (외부/복합/식별자상속)"
        number item_seq PK "주문순번 (복합식별자 구성)"
        string product_id FK "상품번호 (외부식별자)"
        number quantity "수량"
        number unit_price "단가"
    }
    PRODUCT {
        string product_id PK "상품번호 (주식별자)"
        string product_name "상품명"
        number price "가격"
    }
